package edu.daa.dna.service;
import edu.daa.dna.algorithm.DynamicProgramming;import edu.daa.dna.model.ApiModels.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class BenchmarkService {
 public BenchmarkResponse run(BenchmarkRequest q){int size=q.size()==null?100:Math.min(q.size(),2000), reps=q.repetitions()==null?5:Math.max(1,Math.min(q.repetitions(),20));if(size<1)throw new IllegalArgumentException("Benchmark sequence length must be between 1 and 2,000.");long seed=q.seed()==null?42:q.seed();Random r=new Random(seed);String a=dna(size,r),b=dna(size,r);String problem=q.problem()==null?"LCS":q.problem().toUpperCase();if(!problem.equals("LCS")&&!problem.equals("EDIT"))throw new IllegalArgumentException("Problem must be LCS or EDIT.");List<String> names=q.algorithms()==null||q.algorithms().isEmpty()?List.of("MEMOIZATION","TABULATION","ROLLING_ROWS"):q.algorithms();if(size>500&&names.stream().anyMatch(n->n.equalsIgnoreCase("MEMOIZATION")))throw new IllegalArgumentException("Memoization benchmarks are limited to 500 bases per sequence for recursion safety.");List<BenchmarkResult>out=new ArrayList<>();for(String name:names){if(!Set.of("MEMOIZATION","TABULATION","ROLLING_ROWS").contains(name.toUpperCase()))throw new IllegalArgumentException("Unsupported benchmark algorithm: "+name);for(int i=0;i<2;i++)run(problem,name,a,b);long[] times=new long[reps];int answer=0;for(int i=0;i<reps;i++){long t=System.nanoTime();answer=run(problem,name,a,b);times[i]=System.nanoTime()-t;}Arrays.sort(times);int expected=problem.equals("LCS")?DynamicProgramming.lcsRolling(a,b):DynamicProgramming.editRolling(a,b);long med=reps%2==1?times[reps/2]:(times[reps/2-1]+times[reps/2])/2;out.add(new BenchmarkResult(name,problem,size,size,med,Math.round(med/10000.0)/100.0,"O(mn)",name.equalsIgnoreCase("ROLLING_ROWS")?"O(min(m,n))":"O(mn)",answer==expected));}return new BenchmarkResponse(seed,reps,q.pattern()==null?"uniform random DNA":q.pattern(),out);}
 private int run(String p,String n,String a,String b){boolean l=p.equals("LCS");return switch(n.toUpperCase()){case "MEMOIZATION"->l?DynamicProgramming.lcsMemo(a,b):DynamicProgramming.editMemo(a,b);case "ROLLING_ROWS"->l?DynamicProgramming.lcsRolling(a,b):DynamicProgramming.editRolling(a,b);default->l?DynamicProgramming.lcsTable(a,b)[a.length()][b.length()]:DynamicProgramming.editTable(a,b)[a.length()][b.length()];};}private String dna(int n,Random r){String x="ACGT";StringBuilder s=new StringBuilder();while(s.length()<n)s.append(x.charAt(r.nextInt(4)));return s.toString();}
}
